import { useEffect, useState } from 'react'

/**
 * Game art generated by Codex (see docs/CODEX_ITEM_ART_BRIEF.md).
 * Every asset is optional: until its file exists in /public/items, the game
 * falls back to the emoji listed here, so nothing ever breaks.
 */
export const GAME_NAME = 'Rally Wahala'
export const GAME_TAGLINE = 'Catch their promises. Vote them out.'

export const ASSETS = {
  // Promise Catcher: promises (good)
  'promise-light': '💡',
  'promise-roads': '🛣️',
  'promise-schools': '📚',
  'promise-hospital': '🏥',
  'promise-jobs': '💼',
  'promise-manifesto': '📜', // golden
  // Promise Catcher: excuses & hardship (bad)
  'bad-fuel': '⛽',
  'bad-tax': '🧾',
  'bad-excuse': '💬',
  // Promise Catcher: power-ups
  'power-megaphone': '🧲',
  'power-double': '⭐',
  'power-shield': '🛡️',
  'power-slow': '🐢',
  'power-heart': '❤️',
  // Promise Catcher: the player's basket
  'receipt-bag': '🧺',
  // Whack-a-Politician
  'whack-hammer': '🔨',
  'whack-clock': '⏱️',
  'citizen-1': '👩🏾‍🌾',
  'citizen-2': '👨🏾‍🔧',
  'citizen-3': '👩🏾‍🎓',
  'citizen-4': '👨🏾‍🍳',
  'citizen-5': '👵🏾',
  'citizen-6': '👨🏾‍💼',
} as const

export type AssetKey = keyof typeof ASSETS
export const assetUrl = (k: AssetKey) => `/items/${k}.webp`

const cache = new Map<AssetKey, HTMLImageElement | null>()
const listeners = new Set<() => void>()

let started = false

/**
 * Load the generated art listed in /items/manifest.json (written by
 * scripts/optimize-art.py). Missing manifest or files = emoji fallbacks.
 */
export function preloadAssets() {
  if (started) return
  started = true
  fetch('/items/manifest.json')
    .then((r) => (r.ok ? (r.json() as Promise<string[]>) : []))
    .catch(() => [] as string[])
    .then((keys) => {
      for (const k of keys) {
        if (!(k in ASSETS)) continue
        const key = k as AssetKey
        const img = new Image()
        img.onload = () => {
          cache.set(key, img)
          listeners.forEach((l) => l())
        }
        img.src = assetUrl(key)
      }
    })
}

/** The loaded image for canvas drawing, or null (use the emoji fallback). */
export const getAsset = (k: AssetKey) => cache.get(k) ?? null

/** React hook: re-renders when generated art finishes loading. */
export function useAssetsReady() {
  const [, force] = useState(0)
  useEffect(() => {
    const l = () => force((n) => n + 1)
    listeners.add(l)
    return () => {
      listeners.delete(l)
    }
  }, [])
}

/** DOM helper: render the generated image if present, otherwise the emoji. */
export function AssetIcon({ k, className, size }: { k: AssetKey; className?: string; size: number }) {
  useAssetsReady()
  const img = getAsset(k)
  if (img) return <img src={img.src} alt="" draggable={false} className={className} style={{ width: size, height: size, objectFit: 'contain' }} />
  return (
    <span className={className} style={{ fontSize: size * 0.85, lineHeight: 1 }}>
      {ASSETS[k]}
    </span>
  )
}
